describe('ToolRegistry schema compilation', () => {
  it('rejects an invalid location type at registration @specs/hal-engine-tool-input-validation/spec.md#5', () => {
    const registry = new ToolRegistry();
    let error: unknown;
    try {
      registry.register(
        {
          name: 'get_weather',
          description: 'Get weather for a location',
          inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
        },
        async input => JSON.stringify(input)
      );
    } catch (cause) {
      error = cause;
    }
    expect({error, registered: registry.has('get_weather')}).toEqual({
      error: expect.objectContaining({message: expect.stringMatching(/get_weather/)}),
      registered: false,
    });
  });
});

it('rejects missing location before execution @specs/hal-engine-tool-input-validation/spec.md#1', async () => {
  const registry = new ToolRegistry();
  const executed: Record<string, unknown>[] = [];
  registry.register(
    {
      name: 'weather',
      description: 'Weather',
      inputSchema: {
